import java.util.Scanner;

public class Main {
    static final int INF = 0x3f3f3f3f;
    static int[] pi, kk, iq, pq, bb;
    static int cnt;

    // LT macro
    static boolean lt(int u, int v) {
        return pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]);
    }

    static int i2(int i) {
        int t = i * 2;
        if (t > cnt) return 0;
        if (t < cnt && lt(pq[t + 1], pq[t])) return t + 1;
        return t;
    }

    static void pq_up(int u) {
        int i = iq[u];
        while (i > 1) {
            int j = i / 2;
            if (!lt(u, pq[j])) break;
            iq[pq[j]] = i;
            pq[i] = pq[j];
            i = j;
        }
        iq[u] = i;
        pq[i] = u;
    }

    static void pq_dn(int u) {
        int i = iq[u];
        while (true) {
            int j = i2(i);
            if (j == 0 || !lt(pq[j], u)) break;
            iq[pq[j]] = i;
            pq[i] = pq[j];
            i = j;
        }
        iq[u] = i;
        pq[i] = u;
    }

    static void pq_add(int u) {
        iq[u] = ++cnt;
        pq_up(u);
    }

    static int pq_remove_first() {
        int u = pq[1];
        int v = pq[cnt--];
        iq[v] = 1;
        pq_dn(v);
        return u;
    }

    // original graph adjacency (small)
    static int[] headOrig;
    static int[] toOrig, nextOrig;
    static int edgeCntOrig;

    // flow graph adjacency (large)
    static int n_, m_max;
    static int[] headFlow, toFlow, nextFlow;
    static int flowEdgeIdx;

    // flow graph edges
    static int[] uu, vv, uv, cost, cost_, cc;

    static void add_orig(int i, int j) {
        edgeCntOrig++;
        toOrig[edgeCntOrig] = j;
        nextOrig[edgeCntOrig] = headOrig[i];
        headOrig[i] = edgeCntOrig;
    }

    static void add_flow(int i, int h_) {
        flowEdgeIdx++;
        toFlow[flowEdgeIdx] = h_; // h_ is the edge index ( including direction bit )
        nextFlow[flowEdgeIdx] = headFlow[i];
        headFlow[i] = flowEdgeIdx;
    }

    static void link(int u, int v, int cap, int cos) {
        int h = m_max;
        // We'll allocate arrays of size m_max+1, so we use m_max as next index
        // but we start from 0, so we need to increment m_max after assigning
        // Actually we will allocate arrays with size computed from formula,
        // then fill as we go. We'll use a separate variable m_cnt.
        // Let's redefine: we'll keep a counter m_cnt = number of links added so far.
        // The arrays are sized up to maxM, and we will index by m_cnt.
    }

    static void dijkstra(int s) {
        for (int i = 0; i < n_; i++) pi[i] = INF;
        pi[s] = 0;
        cnt = 0;
        for (int i = 0; i < n_; i++) iq[i] = 0;
        pq_add(s);
        while (cnt > 0) {
            int u = pq_remove_first();
            for (int e = headFlow[u]; e != 0; e = nextFlow[e]) {
                int h_ = toFlow[e];
                if (cc[h_] == 0) continue;
                int h = h_ >> 1;
                int p = pi[u] + (((h_ & 1) == 0) ? cost_[h] : -cost_[h]);
                int v = u ^ uv[h];
                if (pi[v] == INF) {
                    pi[v] = p;
                    kk[v] = kk[u] + 1;
                    bb[v] = h_;
                    pq_add(v);
                } else if (pi[v] > p || (pi[v] == p && kk[v] > kk[u] + 1)) {
                    pi[v] = p;
                    kk[v] = kk[u] + 1;
                    bb[v] = h_;
                    pq_up(v);
                }
            }
        }
    }

    static void push(int s, int t) {
        for (int u = t; u != s; u ^= uv[bb[u] >> 1]) {
            int h_ = bb[u];
            cc[h_]--;
            cc[h_ ^ 1]++;
        }
    }

    static int edmonds_karp(int s, int t) {
        System.arraycopy(cost, 0, cost_, 0, m_max);
        while (true) {
            dijkstra(s);
            if (pi[t] == INF) break;
            push(s, t);
            for (int h = 0; h < m_max; h++) {
                if (pi[uu[h]] != INF && pi[vv[h]] != INF) {
                    cost_[h] += pi[uu[h]] - pi[vv[h]];
                }
            }
        }
        int c = 0;
        for (int h = 0; h < m_max; h++) {
            c += cost[h] * cc[(h << 1) | 1];
        }
        return c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        int[] ii = new int[k];
        for (int h = 0; h < k; h++) {
            ii[h] = sc.nextInt() - 1;
        }

        // Build original graph adjacency
        headOrig = new int[n + 1];
        toOrig = new int[2 * m + 2];
        nextOrig = new int[2 * m + 2];
        edgeCntOrig = 0;
        for (int h = 0; h < m; h++) {
            int i = sc.nextInt() - 1;
            int j = sc.nextInt() - 1;
            add_orig(i, j);
            add_orig(j, i);
        }

        int t = n + k + 1;
        n_ = n * t + 1;
        // Compute exact max number of flow edges (links)
        int maxM = k + (m * 2 * k + n) * (t - 1); // as in original #define
        m_max = maxM; // use this as allocated size
        // Allocate flow graph edge arrays
        // They store edges: each link adds one edge (h) with two entries in adjacency
        // So we need adjacency arrays of size 2*maxM
        headFlow = new int[n_];
        toFlow = new int[2 * maxM + 2];
        nextFlow = new int[2 * maxM + 2];
        flowEdgeIdx = 0;

        uu = new int[maxM];
        vv = new int[maxM];
        uv = new int[maxM];
        cost = new int[maxM];
        cost_ = new int[maxM];
        cc = new int[2 * maxM];

        // pi, kk, iq, pq, bb arrays for Dijkstra
        pi = new int[n_];
        kk = new int[n_];
        iq = new int[n_];
        pq = new int[n_ + 1];
        bb = new int[n_];

        int m_cnt = 0; // number of links added so far

        // For each original edge, add flow edges for each time step and for each x
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                for (int e = headOrig[i]; e != 0; e = nextOrig[e]) {
                    int j = toOrig[e];
                    int v = j * t + s + 1;
                    int u = i * t + s;
                    for (int x = 1; x <= k; x++) {
                        // link(u, v, 1, c + (x*2-1)*d)
                        int h = m_cnt;
                        uu[h] = u;
                        vv[h] = v;
                        uv[h] = u ^ v;
                        cost[h] = c + (x * 2 - 1) * d;
                        cc[h << 1] = 1;
                        cc[h << 1 | 1] = 0;
                        // Add adjacency entries
                        flowEdgeIdx++;
                        toFlow[flowEdgeIdx] = h << 1;
                        nextFlow[flowEdgeIdx] = headFlow[u];
                        headFlow[u] = flowEdgeIdx;
                        flowEdgeIdx++;
                        toFlow[flowEdgeIdx] = h << 1 | 1;
                        nextFlow[flowEdgeIdx] = headFlow[v];
                        headFlow[v] = flowEdgeIdx;
                        m_cnt++;
                    }
                }
            }
        }

        // Stay edges: for each node and each time step, link u to u+1
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                int v = u + 1;
                int h = m_cnt;
                uu[h] = u;
                vv[h] = v;
                uv[h] = u ^ v;
                cost[h] = (i == 0 ? 0 : c);
                cc[h << 1] = k;
                cc[h << 1 | 1] = 0;
                // adjacency entries
                flowEdgeIdx++;
                toFlow[flowEdgeIdx] = h << 1;
                nextFlow[flowEdgeIdx] = headFlow[u];
                headFlow[u] = flowEdgeIdx;
                flowEdgeIdx++;
                toFlow[flowEdgeIdx] = h << 1 | 1;
                nextFlow[flowEdgeIdx] = headFlow[v];
                headFlow[v] = flowEdgeIdx;
                m_cnt++;
            }
        }

        // Source edges: from virtual source (n_ - 1) to each employee start node
        for (int h = 0; h < k; h++) {
            int u = n_ - 1;
            int v = ii[h] * t + 0;
            int edgeH = m_cnt;
            uu[edgeH] = u;
            vv[edgeH] = v;
            uv[edgeH] = u ^ v;
            cost[edgeH] = 0;
            cc[edgeH << 1] = 1;
            cc[edgeH << 1 | 1] = 0;
            // adjacency entries
            flowEdgeIdx++;
            toFlow[flowEdgeIdx] = edgeH << 1;
            nextFlow[flowEdgeIdx] = headFlow[u];
            headFlow[u] = flowEdgeIdx;
            flowEdgeIdx++;
            toFlow[flowEdgeIdx] = edgeH << 1 | 1;
            nextFlow[flowEdgeIdx] = headFlow[v];
            headFlow[v] = flowEdgeIdx;
            m_cnt++;
        }

        // The total number of links added should be equal to maxM
        // (we computed maxM exactly, so m_cnt == maxM)
        m_max = m_cnt;

        // Compute min cost flow
        int result = edmonds_karp(n_ - 1, 0 * t + t - 1);
        System.out.println(result);

        sc.close();
    }
}
